#version 300 es

#define MODE_SIMPLE_COPY

#define samplerExternalOES sampler2D
#ifdef USE_MULTIVIEW
#if defined(GL_OVR_multiview2)
#extension GL_OVR_multiview2 : require
#elif defined(GL_OVR_multiview)
#extension GL_OVR_multiview : require
#endif
layout(num_views=2) in;
#define ViewIndex gl_ViewID_OVR
#define MAX_VIEWS 2
#else
#define ViewIndex uint(0)
#define MAX_VIEWS 1
#endif
precision highp float;
precision highp int;
precision highp sampler2D;
precision highp samplerCube;
precision highp sampler2DArray;
precision highp sampler3D;

layout(location = 0) in vec2 vertex_attrib;

out vec2 uv_interp;
/* clang-format on */

#if defined(USE_COPY_SECTION) || defined(MODE_GAUSSIAN_BLUR)
// Defined in 0-1 coords.
uniform highp vec4 copy_section;
#endif
#if defined(MODE_GAUSSIAN_BLUR) || defined(MODE_COPY_FROM)
uniform highp vec4 source_section;
#endif

void main() {
	uv_interp = vertex_attrib * 0.5 + 0.5;
	gl_Position = vec4(vertex_attrib, 1.0, 1.0);

#if defined(USE_COPY_SECTION) || defined(MODE_GAUSSIAN_BLUR)
	gl_Position.xy = (copy_section.xy + uv_interp.xy * copy_section.zw) * 2.0 - 1.0;
#endif
#if defined(MODE_GAUSSIAN_BLUR) || defined(MODE_COPY_FROM)
	uv_interp = source_section.xy + uv_interp * source_section.zw;
#endif
}

/* clang-format off */

